def _quantile_sample(uniforms: torch.Tensor, tables: list[list[float]]) -> torch.Tensor:
    probabilities = torch.tensor(QUANTILE_PROBABILITIES,dtype=torch.float32,device='cpu')
    table = torch.tensor(tables,dtype=torch.float32,device='cpu')
    # Uniforms use [T,H,D] or [T,H]. Quantile tables are indexed by head.
    lower = torch.searchsorted(probabilities,uniforms.contiguous(),right=True).sub(1).clamp(0,len(probabilities)-2)
    fraction = (uniforms-probabilities[lower])/(probabilities[lower+1]-probabilities[lower])
    heads = torch.arange(table.shape[0],device='cpu').view(1,-1,*([1] if uniforms.ndim==3 else []))
    return table[heads,lower]*(1-fraction)+table[heads,lower+1]*fraction


def _state(profile, generator):
    spectrum=torch.tensor(profile['singular_values'],dtype=torch.float32,device='cpu')
    means=torch.tensor(profile['head_mean'],dtype=torch.float32,device='cpu')[:,None,None]
    row=torch.tensor(profile['row_scale'],dtype=torch.float32,device='cpu')[:,:,None]
    column=torch.tensor(profile['column_scale'],dtype=torch.float32,device='cpu')[:,:,None]
    left=torch.linalg.qr(torch.randn((24,128,128),generator=generator,dtype=torch.float32,device='cpu')*row.clamp_min(1e-12)).Q
    right=torch.linalg.qr(torch.randn((24,128,128),generator=generator,dtype=torch.float32,device='cpu')*column.clamp_min(1e-12)).Q
    left*=torch.randint(2,(24,1,128),generator=generator,device='cpu')*2-1
    right*=torch.randint(2,(24,1,128),generator=generator,device='cpu')*2-1
    return (left*spectrum[:,None,:])@right.transpose(-1,-2)+means


def _make_inputs(requests: int, ssm_state_indices: list[list[int]] | None=None,
                 num_accepted_tokens: list[int] | None=None, seed: int | None=None,
                 dtype: str='bfloat16', device: str='cuda') -> dict[str,object]:
    if type(requests) is not int or not 1<=requests<=16 or dtype!='bfloat16':
        raise ValueError('requests or dtype differs from the captured TP2 C16 decode ABI')
    seed = (torch.initial_seed() % (2**63)) if seed is None else seed
    if type(seed) is not int or not 0<=seed<2**63:raise ValueError('invalid seed')
    indices=[[134+19*i+j for j in range(4)] for i in range(requests)] if ssm_state_indices is None else ssm_state_indices
    accepted=[1+i%4 for i in range(requests)] if num_accepted_tokens is None else num_accepted_tokens
    if not isinstance(indices,list) or len(indices)!=requests or any(not isinstance(row,list) or len(row)!=4 or any(type(slot) is not int or not -1<=slot<1282 for slot in row) for row in indices):
        raise ValueError('state indices must be [N,4] within the pool')
    if not isinstance(accepted,list) or len(accepted)!=requests or any(type(n) is not int or not 1<=n<=4 for n in accepted):
        raise ValueError('accepted tokens must be [N] in [1,4]')
    valid=[slot for row in indices for slot in row if slot>=0]
    if len(valid)!=len(set(valid)) or any(indices[i][n-1]<0 for i,n in enumerate(accepted)):
        raise ValueError('state writes must be unique and selected initial slots valid')
    generator=torch.Generator(device='cpu').manual_seed(seed)
    tokens=4*requests
    values={}
    for name,heads in (('q',8),('k',8),('v',24)):
        uniforms=torch.rand((tokens,heads,128),generator=generator,dtype=torch.float32,device='cpu')
        values[name]=_quantile_sample(uniforms,PROFILES[name]).unsqueeze(0).to(device=device,dtype=torch.bfloat16)
    noise=torch.randn((tokens,24,2),generator=generator,dtype=torch.float32,device='cpu')
    corr=torch.tensor(GATE_BETA_CORRELATION,dtype=torch.float32,device='cpu')
    gu=(noise[:,:,0]/math.sqrt(2)).erf().add(1).mul(.5)
    bu=((corr*noise[:,:,0]+(1-corr.square()).clamp_min(0).sqrt()*noise[:,:,1])/math.sqrt(2)).erf().add(1).mul(.5)
    g=-_quantile_sample(gu,PROFILES['g']).exp().unsqueeze(0).to(device=device)
    beta=_quantile_sample(bu,PROFILES['beta']).clamp(0,1).unsqueeze(0).to(device=device,dtype=torch.bfloat16)
    backing=torch.zeros(15360+1282*458752,dtype=torch.float32,device=device)
    pool=backing.as_strided((1282,24,128,128),(458752,16384,128,1),15360)
    selected=[indices[i][n-1] for i,n in enumerate(accepted)]
    sentinels=[slot for slot in range(1282) if slot not in set(valid)][:8]
    for slot in selected+sentinels:
        profile=STATE_PROFILES[int(torch.randint(len(STATE_PROFILES),(1,),generator=generator,device='cpu'))]
        pool[slot].copy_(_state(profile,generator).to(device=device))
    return {'q':values['q'],'k':values['k'],'v':values['v'],'g':g,'beta':beta,
            'initial_state':pool,'inplace_final_state':True,
            'cu_seqlens':torch.arange(requests+1,dtype=torch.int32,device=device)*4,
            'ssm_state_indices':torch.tensor(indices,dtype=torch.int32,device=device),
            'num_accepted_tokens':torch.tensor(accepted,dtype=torch.int32,device=device),
            'retrieve_parent_token':None,'use_qk_l2norm_in_kernel':True}
